CREATE OR REPLACE FUNCTION public.guard_forecastsnapshot_publication()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
            BEGIN
                IF OLD.available_at IS NOT NULL
                    OR to_jsonb(NEW) - 'available_at' <> to_jsonb(OLD) - 'available_at' THEN
                    RAISE EXCEPTION 'Forecast snapshot acquisitions are immutable'
                        USING ERRCODE = '23514';
                END IF;
                RETURN NEW;
            END;
            $function$
